  // Groups — the lesson changes tab
  "O'chirishda xatolik": "Ошибка при удалении",
  "Bekor qilingan dars yozuvini o'chirmoqchimisiz?": "Удалить запись об отменённом занятии?",
  "Bekor qilishda o'quvchilarga qaytarilgan dars puli ulardan qayta yechiladi; shundan beri muzlatilgan yoki guruhdan chiqqan o'quvchining puli qoladi. Davomat tiklanmaydi. Agar dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "Деньги за занятие, возвращённые ученикам при отмене, будут списаны с них снова; у ученика, который с тех пор был заморожен или вышел из группы, деньги остаются. Посещаемость не восстанавливается. Если время занятия уже прошло, оно снова попадёт в вопрос «Занятие состоялось?».",
  "Bekor qilingan dars yozuvi o'chirildi": "Запись об отменённом занятии удалена",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi, {kept} o'quvchida qoldi": "Отмена удалена. Повторно списано: {amount} сум (учеников: {n}). Деньги остались у учеников: {kept}",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi": "Отмена удалена. Повторно списано: {amount} сум (учеников: {n})",
  "O'rinbosar ustoz qoidasini bekor qilmoqchimisiz?": "Отменить назначение замещающего преподавателя?",
  "Oddiy guruh ustozlariga qaytariladi va ularning oyligi qayta hisoblanadi.": "Занятие вернётся обычным преподавателям группы, а их зарплата будет пересчитана.",
  "O'rinbosar bekor qilindi": "Замена отменена",
  "Ko'chirish yozuvini o'chirmoqchimisiz?": "Удалить запись о переносе?",
  "Diqqat: bu ikkala sanada (asl va yangi) davomatni avtomatik tiklamaydi. Agar asl dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "Внимание: посещаемость на обе даты (исходную и новую) автоматически не восстанавливается. Если время исходного занятия уже прошло, оно снова попадёт в вопрос «Занятие состоялось?».",
  "Ko'chirish yozuvi o'chirildi": "Запись о переносе удалена",
  "Sana va sababni kiriting": "Укажите дату и причину",
  "Dars bekor qilindi": "Занятие отменено",
  "Bekor qilishda xatolik": "Ошибка при отмене",
  "Agar bu kuni davomat allaqachon olingan bo'lsa, har bir o'quvchining holati \"uzrli sabab bilan kelmadi\" ga o'tadi va undan yechilgan pul qaytariladi (qoldiq darslar hisobi 1 ga oshadi).": "Если в этот день посещаемость уже отмечена, статус каждого ученика станет «не пришёл по уважительной причине», а списанные с него деньги вернутся (счётчик оставшихся занятий увеличится на 1).",
  "Bekor qilinadigan dars sanasi": "Дата отменяемого занятия",
  "Faqat ushbu guruh dars qiladigan sanalar ko'rinadi": "Показаны только даты, когда у этой группы бывают занятия",
  "Ustoz kasal, bayram, va h.k.": "Преподаватель болеет, праздник и т. д.",
  "Kamida 1 ta ustoz bo'lishi kerak": "Должен быть хотя бы один преподаватель",
  "O'rinbosar saqlandi": "Замена сохранена",
  "Saqlashda xatolik": "Ошибка при сохранении",
  "Darsga o'rinbosar ustoz tayinlash": "Назначить замещающего преподавателя на занятие",
  "Tanlangan kungi dars uchun ustozlarni almashtiring. Agar bu kuni davomat allaqachon olingan bo'lsa, oylik avtomatik qayta hisoblanadi (eski ustozlardan olib tashlanib, yangilarga yoziladi).": "Замените преподавателей на занятие выбранного дня. Если в этот день посещаемость уже отмечена, зарплата пересчитается автоматически (она снимается у прежних преподавателей и начисляется новым).",
  "Dars sanasi": "Дата занятия",
  "Ushbu guruh dars qiladigan kunlar; ko'chirilgan sanalar ham ro'yxatda chiqadi": "Дни, когда у этой группы бывают занятия; перенесённые даты тоже есть в списке",
  "Bu darsni o'tadigan ustozlar": "Преподаватели этого занятия",
  "Odatda: guruhning {n} ta standart ustozi. Tanlovni o'zgartirsangiz, faqat tanlanganlarga oylik yoziladi.": "По умолчанию: стандартных преподавателей группы — {n}. Если изменить выбор, зарплата начисляется только выбранным.",
