  "Asl sana o'zgartirib bo'lmaydi (audit yozuvi). Yangi sana, vaqt, xona va sababni o'zgartirishingiz mumkin.": "Исходную дату изменить нельзя (запись аудита). Можно изменить новую дату, время, аудиторию и причину.",
  "Bu kungi dars yangi sanaga o'tkaziladi. Asl kunda davomat olingan bo'lsa, to'lov va oylik avtomatik qaytariladi.": "Занятие этого дня переносится на новую дату. Если в исходный день посещаемость уже отмечена, оплата и зарплата возвращаются автоматически.",
