  "Tanlangan sana va vaqtda bu filialda bo'sh xona yo'q. Vaqtni o'zgartiring yoki boshqa kunni tanlang.": "В выбранные дату и время в этом филиале нет свободных аудиторий. Измените время или выберите другой день.",
