  "Oldindan belgilash rejimi — bugun kelmaydigan o'quvchini hozir belgilang. Dars vaqtida ustoz davomatni oladi; belgilangan o'quvchilar \"Sababli\" bo'lib turadi (pul yechilmaydi).": "Режим предварительной отметки — отметьте сейчас ученика, который сегодня не придёт. Во время занятия преподаватель отметит посещаемость; отмеченные ученики остаются «По уважительной причине» (деньги не списываются).",
