  "{n} nafar": "{n} чел.",
  "Ko'rsatkichlarni yuklab bo'lmadi. Sahifani yangilang.": "Не удалось загрузить показатели. Обновите страницу.",
  "Oylik dinamikasi": "Динамика зарплаты",
  "{month}: {amount}": "{month}: {amount}",
  "{month} (davom etmoqda): {amount}": "{month} (идёт): {amount}",
  "Har oy to'liq ishlangan pul — «Ish haqi» bo'limidagi raqamning o'zi.\nJoriy oy hali tugamagan: raqam oy oxirigacha o'sadi.": "Сумма, полностью заработанная за каждый месяц — то же число, что в разделе «Зарплата».\nТекущий месяц ещё не закончился: цифра будет расти до конца месяца.",
  "Bu oylarda oylik yo'q": "В эти месяцы зарплаты нет",
  "Oylik": "Зарплата",
  "Hozir: {n} nafar": "Сейчас: {n} чел.",
  "Har oy oxirida ustoz guruhlarida o'qiyotgan o'quvchilar soni.\nGuruh boshqa ustozga o'tgan oydan boshlab sanalmaydi.": "Число учеников, занимающихся в группах преподавателя на конец каждого месяца.\nС месяца, когда группа перешла к другому преподавателю, они не считаются.",
  "Kelganlar va ketganlar": "Пришли и ушли",
  "{month}: +{joined} qo'shildi, −{left} ketdi": "{month}: +{joined} пришли, −{left} ушли",
  "Yashil — ustoz guruhiga qo'shilganlar (boshqa guruhdan o'tganlar ham).\nQizil — markazdan ketganlar («Ketganlar» hisobotidagi qoida).\nOch qizil — to'xtagan, lekin hali qaytishi mumkin (21 kun, muzlatishda 60 kun).": "Зелёный — присоединившиеся к группам преподавателя (в том числе перешедшие из другой группы).\nКрасный — ушедшие из центра (правило отчёта «Ушедшие»).\nСветло-красный — перестали ходить, но ещё могут вернуться (21 день, при заморозке 60 дней).",
  "Bu oylarda kelgan ham, ketgan ham yo'q": "В эти месяцы никто не пришёл и не ушёл",
  "Qaytishi mumkin": "Могут вернуться",
  "{month}: {pct}%": "{month}: {pct}%",
  "Kelgan va kechikkanlar ÷ (kelgan + kechikkan + kelmagan).\nSababli va bekor qilingan darslar hisobga olinmaydi.": "Пришедшие и опоздавшие ÷ (пришли + опоздали + не пришли).\nЗанятия с уважительной причиной и отменённые не учитываются.",
  "Bu oylarda davomat olinmagan": "В эти месяцы посещаемость не отмечалась",
  "Hech qanday muhim o'zgarish topilmadi": "Значимых изменений не найдено",
  "{month} — bu oy qo'lda kiritilgan, har bir dars bo'yicha ma'lumot yo'q. Faqat kiritilgan summa va avans ko'rsatilgan.": "{month} — этот месяц внесён вручную, данных по каждому занятию нет. Показаны только внесённая сумма и аванс.",
  "{month} uchun oylik ma'lumoti yo'q — boshqa oyni tanlab ko'ring.": "Нет данных о зарплате за {month} — выберите другой месяц.",
  "To'lanishi kerak": "К выплате",
  "Bu oy uchun to'lanishi kerak bo'lgan sof summa: to'liq ishlangan (markaz qo'shimchasi bilan) − avans. Hisoblab bo'lingan oylar uchun haqiqiy to'langan summa ko'rsatiladi.": "Чистая сумма к выплате за этот месяц: заработано полностью (с доплатой центра) − аванс. Для рассчитанных месяцев показана фактически выплаченная сумма.",
  "Oylik (belgilangan)": "Оклад (фиксированный)",
  "Avans": "Аванс",
  "To'liq ishlangan": "Заработано полностью",
  "O'quvchilar to'lagan": "Оплатили ученики",
  "To'liq ishlangandan o'quvchilar haqiqatan to'lagani bilan qoplangan qismi.": "Часть полностью заработанной суммы, покрытая тем, что ученики действительно оплатили.",
  "Markaz qo'shimchasi": "Доплата центра",
  "Markazning o'z hisobidan qo'shgan (yoki oy yopilgunicha qo'shadigan) qismi. Oy yopilgach bu raqam qolaveradi — o'quvchi keyin to'lasa, pul markazga qaytadi, ustozga qayta yozilmaydi. Oylik to'lov kurslarida o'quvchi hali to'lamagan oylik hisobining ulushi ham shu yerda — u to'lagan sari kamayadi.": "Часть, которую центр добавил (или добавит до закрытия месяца) из своих средств. После закрытия месяца эта сумма остаётся прежней: если ученик заплатит позже, деньги вернутся центру и преподавателю повторно не начисляются. В курсах с помесячной оплатой сюда входит и доля ещё не оплаченного учеником месячного начисления — она уменьшается по мере его оплаты.",
  "Shu oy ichida ustozga oldindan berilgan pul (Xarajatlar → Avans). U «To'lanishi kerak»dan allaqachon ayirilgan.": "Деньги, выданные преподавателю заранее в течение этого месяца (Расходы → Аванс). Они уже вычтены из суммы «К выплате».",
  "Shu oy uchun to'lanishi kerak bo'lgan sof summa — avans allaqachon ayirilgan. «Ish haqi» bo'limidagi va Moliya → Oyliklar sahifasidagi raqam bilan bir xil.": "Чистая сумма к выплате за этот месяц — аванс уже вычтен. Совпадает с цифрой в разделе «Зарплата» и на странице Финансы → Зарплаты.",
  "Ishlangan {amount}": "Заработано {amount}",
  "avans −{amount}": "аванс −{amount}",
  "Eslatma — bu summalardan ushlanishi mumkin:": "Примечание — из этих сумм могут быть удержаны:",
