  "Ustozlarga avans — Ish haqi → Avanslar bo'limida. Xodimlar oyligi — Ish haqida; bu yerga yozilmaydi, aks holda foydadan ikki marta ayiriladi.": "Авансы преподавателям — в разделе «Зарплата» → «Авансы». Зарплата сотрудников — в «Зарплате»; сюда она не вносится, иначе будет дважды вычтена из прибыли.",
