  "Qarz turi": "Тип долга",
  "O'qimayotganlar": "Не обучаются",
  "Ketgan": "Выбывший",
  "{month} to'lovini hali to'liq to'lamagan o'qiyotgan o'quvchilar. To'lov muddati — shartnoma bo'yicha oyning 2-darsigacha.": "Обучающиеся ученики, которые ещё не полностью внесли оплату за {month}. Срок оплаты по договору — до 2-го занятия месяца.",
  "O'qiyotgan, lekin o'tgan oylardan qarzi qolgan o'quvchilar. Shartnomaga ko'ra 2-darsga kirish uchun eski qarz ham to'lanishi kerak.": "Обучающиеся ученики с долгом за прошлые месяцы. По договору, чтобы попасть на 2-е занятие, нужно погасить и старый долг.",
  "Hozir hech qaysi guruhda o'qimayotganlar: guruhsiz qolgan, muzlatilgan yoki ketgan. Bu — undirish ro'yxati: qo'ng'iroq, va'da, to'lov.": "Сейчас не учатся ни в одной группе: остались без группы, заморожены или выбыли. Это список для взыскания: звонок, обещание, оплата.",
