  "Saralash": "Сортировка",
  "Barcha qarzdorlar — hozir o'qiyotgani ham, ketgani ham.": "Все должники — и те, кто сейчас учится, и выбывшие.",
  "Qarz oyma-oy qanday o'zgargan: qancha qo'shilgan, qanchasi to'langan va oy oxirida qancha qolgan.": "Как долг менялся по месяцам: сколько добавилось, сколько оплачено и сколько осталось в конце месяца.",
  "Butun kompaniya bo'yicha — bu jadval filialga bo'linmaydi.": "По всей компании — эта таблица не делится по филиалам.",
  "O'quvchi o'qishni tashlagani uchun undirilmaydigan deb belgilangan qarzlar.": "Долги, признанные невзыскиваемыми, потому что ученик бросил учёбу.",
  "Markaz o'quvchilar to'lamagan darslar uchun ustozlarga pul to'lab bergan. Bu yerda o'sha pul kimdan undirilishi kerakligi ko'rinadi.": "Центр заплатил преподавателям за занятия, которые ученики не оплатили. Здесь видно, с кого нужно взыскать эти деньги.",
  "Davr tanlovi qaysi oydagi darslar hisobga olinishini belgilaydi — o'quvchining qarz summasi o'zgarmaydi.": "Выбор периода определяет, занятия какого месяца учитываются, — сумма долга ученика не меняется.",
  "Butun davr": "Весь период",
  "Markaz qoplagan, hali qaytmagan dars yo'q — hammasi undirilgan.": "Нет занятий, покрытых центром и ещё не возвращённых, — всё взыскано.",
  "{month}da markaz qoplagan dars yo'q — bu oyda hali dars o'tilmagan yoki hamma o'quvchi to'lagan.": "За {month} нет занятий, покрытых центром, — в этом месяце ещё не было занятий или все ученики оплатили.",
  "Markaz to'laydi": "Центр заплатит",
  "Markaz to'lagan": "Центр заплатил",
  "Oy yopilganda ustozlarga chiqadi — hali chiqmagan": "Выдаётся преподавателям при закрытии месяца — ещё не выдано",
  "Kassadan ustozlarga chiqqan pul": "Деньги, выданные из кассы преподавателям",
  "Qoplanishi kerak": "Нужно покрыть",
  "Hali qaytmagan": "Ещё не возвращено",
  "Oy yopilguncha undirilsa, markaz to'lamaydi": "Если взыскать до закрытия месяца, центр не заплатит",
  "Chiqqan puldan hali undirilmagani": "Ещё не взысканная часть выданных денег",
  "{n} ta dars qoplanadi": "Занятий будет покрыто: {n}",
  "{n} ta dars qoplangan": "Покрыто занятий: {n}",
  "Faol emas": "Неактивные",
  "Darsga kelmaydi — pul o'zi qaytmaydi": "Не ходят на занятия — деньги сами не вернутся",
  "{month} oyligi hali yopilmagan.": "Зарплата за {month} ещё не закрыта.",
  "Darslar o'tilgan, lekin markaz ustozlarga hali to'lagani yo'q — bu pul oy yopilganda chiqadi. Ya'ni hozir undirilsa, markaz umuman to'lamaydi.": "Занятия проведены, но центр ещё не заплатил преподавателям — эти деньги уйдут при закрытии месяца. То есть если взыскать сейчас, центр вообще не заплатит.",
  "filtrlangan": "с фильтром",
  "«Markaz hali olmagan» — jami qarzning markaz ustozlarga chiqarib bo'lgan qismi. «Jami qarzi» esa o'quvchining profilidagi to'liq qarzi: unga markaz qoplamagan oldingi oylar ham kiradi, qaysilari ekani «⧉» nishonida.": "«Центр ещё не получил» — часть общего долга, которую центр уже выплатил преподавателям. «Общий долг» — полный долг из профиля ученика: в него входят и предыдущие месяцы, не покрытые центром; какие именно — на значке «⧉».",
  "Oylik sahifasidagi kartada {amount} turibdi — farqi puli to'liq qaytgan {n} o'quvchi, ular bu ro'yxatda ko'rinmaydi.": "На карточке страницы зарплат стоит {amount} — разница приходится на учеников, чьи деньги полностью вернулись (учеников: {n}); в этом списке их нет.",
  "{n} ta o'quvchi faol emas (muzlatilgan / chetlatilgan / arxiv). Ular darsga kelmaydi, ya'ni bu pul o'z-o'zidan qaytmaydi — ular bilan bog'lanish kerak.": "Неактивных учеников: {n} (заморожены / отчислены / в архиве). Они не ходят на занятия, то есть эти деньги сами не вернутся — с ними нужно связаться.",
  "Ism, telefon yoki ID bo'yicha qidirish…": "Поиск по имени, телефону или ID…",
