  // Payments — «Ish haqi» page, table, drawer, pay dialog, advances
  "Xodim": "Сотрудник",
  "Stavkalar": "Ставки",
  "Avans berish": "Выдать аванс",
  "Avanslar": "Авансы",
  "Markaz qoplagani": "Покрыто центром",
  "Ism yoki ID": "Имя или ID",
  "Jadvalda «O'quvchilar to'lagan / Markaz qo'shdi» ustunlari yo'q — ular xodim oynasida. «Avans» — aynan shu oylikdan ushlanadigan summa. Hisoblash davri doim kalendar oyi (1-sanadan).": "В таблице нет столбцов «Оплатили ученики / Центр доплатил» — они в окне сотрудника. «Аванс» — сумма, удерживаемая именно из этой зарплаты. Расчётный период — всегда календарный месяц (с 1-го числа).",
  "Ishdan bo'shagan. Ro'yxatda turibdi, chunki bu oyning puli hali yopilmagan — yopilgach o'zi tushib qoladi.": "Уволен. Остаётся в списке, потому что деньги за этот месяц ещё не закрыты — после закрытия исчезнет сам.",
  "Jami avans": "Всего авансов",
  "Berilgan kunlar": "Дни выдачи",
  "{n} kun": "{n} дн.",
  "Eng katta kun": "Самый крупный день",
  "Bu oyda avans berilmagan — «Avans berish» tugmasi bilan qo'shing.": "В этом месяце авансов не выдавали — добавьте кнопкой «Выдать аванс».",
  "Bu oyda avans berilmagan.": "В этом месяце авансов не выдавали.",
  "{n} ta avans ({amount}) oyligi belgilanmagan xodimga berilgan — oylik belgilanmaguncha hech qaysi oylikdan ushlanmaydi va «Oyliklar» tabida ko'rinmaydi.": "Авансов: {n} ({amount}) выдано сотрудникам без назначенной зарплаты — пока зарплата не назначена, они не удерживаются ни из какой зарплаты и не видны на вкладке «Зарплаты».",
  "{day}-kun, {amount} so'm avans": "{day}-е число, аванс {amount} сум",
  "{day}-kun, avans yo'q": "{day}-е число, аванса нет",
  "Tafsilotni ko'rish uchun kalendardan kun tanlang.": "Выберите день в календаре, чтобы увидеть подробности.",
  "Jami {amount} · {n} ta": "Всего {amount} · авансов: {n}",
  "Bu kunda avans berilmagan.": "В этот день авансов не выдавали.",
  "{name} bergan": "выдал: {name}",
  "Bu kunga avans qo'shish": "Добавить аванс на этот день",
  "Avans yangilandi": "Аванс обновлён",
  "Avans qo'shildi": "Аванс добавлен",
  "Avansni saqlashda xatolik": "Ошибка при сохранении аванса",
  "Avansni tahrirlash": "Редактировать аванс",
  "Avans qo'shish": "Добавить аванс",
  "Xodim o'zgarmaydi. Avans boshqa odamga yozilgan bo'lsa — buni o'chirib, to'g'ri xodimga yangi avans yozing.": "Сотрудника изменить нельзя. Если аванс записан не тому человеку — удалите его и запишите новый аванс нужному сотруднику.",
  "Avans keyingi oylik hisobida ushbu xodimning oyligidan avtomatik ushlab qolinadi": "Аванс автоматически удержится из зарплаты этого сотрудника при следующем расчёте",
  "Avans haqida...": "Об авансе...",
  "Sana o'zgarsa avans hisobotlarda yangi kunga ko'chadi, Kassa oqimidagi harakat esa kiritilgan kunida qoladi.": "Если дата изменится, аванс в отчётах перейдёт на новый день, а движение в кассовом потоке останется в день внесения.",
