  "oyda xodimga kelgan lidlar (o'zi band qilgan yoki unga berilgan, har lid bir marta) dan nechtasida uning «Lid to'lov qildi» natijasi bor. Joriy oyda hali to'lamaganlar ham hisobda.": "сколько из лидов, пришедших к сотруднику за месяц (закреплённых им самим или переданных ему, каждый лид один раз), имеют его результат «Лид оплатил». В текущем месяце учитываются и те, кто ещё не оплатил.",
